const response = $input.first().json;
const config = $('Configure Source').first().json;
const rawJobs = Array.isArray(response?.data?.jobs) ? response.data.jobs : [];
const limit = Math.min(Math.max(Number(config.maximumResults) || 100, 1), 100);

const employment = (value) => {
  const normalized = String(value || '').toUpperCase().replace(/[^A-Z]/g, '');
  return ({ FULLTIME: 'FULL_TIME', PARTTIME: 'PART_TIME', CONTRACTOR: 'CONTRACT', CONTRACT: 'CONTRACT', TEMPORARY: 'TEMPORARY', INTERN: 'INTERNSHIP', INTERNSHIP: 'INTERNSHIP' })[normalized] || 'UNSPECIFIED';
};
const interval = (value) => {
  const normalized = String(value || '').toUpperCase();
  return ['HOUR', 'DAY', 'WEEK', 'MONTH', 'YEAR'].includes(normalized) ? normalized : 'UNSPECIFIED';
};
const isoOrNull = (value) => {
  if (!value) return null;
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? null : parsed.toISOString();
};
const bounded = (value, size) => value == null ? null : String(value).trim().slice(0, size) || null;

const jobs = rawJobs
  .filter((job) => job?.job_id)
  .slice(0, limit)
  .map((job) => ({
    externalId: String(job.job_id),
    originPublisher: bounded(job.job_publisher, 80),
    company: bounded(job.employer_name, 200),
    title: bounded(job.job_title, 300),
    location: bounded(job.job_location, 300),
    countryCode: /^[A-Za-z]{2}$/.test(String(job.job_country || '')) ? String(job.job_country).toUpperCase() : null,
    workplaceType: job.job_is_remote === true ? 'REMOTE' : 'UNSPECIFIED',
    employmentType: employment(job.job_employment_type),
    department: null,
    team: null,
    description: job.job_description == null ? null : String(job.job_description),
    applyUrl: bounded(job.job_apply_link, 2000),
    sourceUrl: bounded(job.job_google_link || job.job_apply_link, 2000),
    salaryMinimum: Number.isFinite(Number(job.job_min_salary)) ? Number(job.job_min_salary) : null,
    salaryMaximum: Number.isFinite(Number(job.job_max_salary)) ? Number(job.job_max_salary) : null,
    salaryCurrency: /^[A-Za-z]{3}$/.test(String(job.job_salary_currency || '')) ? String(job.job_salary_currency).toUpperCase() : null,
    salaryInterval: interval(job.job_salary_period),
    publishedAt: isoOrNull(job.job_posted_at_datetime_utc),
    sourceUpdatedAt: null,
    expiresAt: isoOrNull(job.job_offer_expiration_datetime_utc),
  }));

if (jobs.length === 0) {
  throw new Error('JSearch returned no records with a stable job_id; nothing was sent');
}

const eventId = `n8n-${$execution.id}-${config.sourceId}`;
return [{ json: {
  eventId,
  ingestionProvider: 'JSEARCH',
  searchRuleId: config.searchRuleId || null,
  query: config.query,
  fetchedAt: new Date().toISOString(),
  jobs,
} }];
